-- 중독백과 치료·회복 23개 본문(body)·심화(advanced) 주입
-- definition(요약) 미변경. id 기준 UPDATE.
-- 실행: psql -h localhost -U postgres -d addiction_news -f inject_recovery.sql
BEGIN;
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "회복은 중독에서 벗어나 건강과 삶의 기능을 되찾아가는 지속적 과정이다. 단순히 물질이나 행동을 멈추는 것을 넘어, 관계·의미·자기효능감을 회복하는 것까지 포함한다. 회복을 완치라는 종착점보다 지속적 관리와 성장의 여정으로 보는 시각이 오늘날 우세하다."}, {"h": "단약과 무엇이 다른가", "p": "사용을 멈추는 것(단약)은 회복의 출발일 뿐 전부가 아니다. 끊어진 관계를 회복하고, 무너진 일상을 재건하고, 삶의 의미와 목적을 다시 세우는 과정이 함께 가야 회복이 지속된다. 그래서 ''무엇을 끊었는가''보다 ''무엇을 세웠는가''가 회복의 실질을 결정한다."}, {"h": "재발을 어떻게 보나", "p": "회복은 직선이 아니라 굴곡의 과정이며, 재발은 흔히 그 여정의 일부로 이해된다. 재발을 도덕적 실패로 낙인찍기보다, 무엇이 부족했는지 배우고 전략을 재조정하는 신호로 다룰 때 회복이 이어진다. 이 관점의 전환이 회복을 포기하지 않게 하는 힘이 된다."}, {"h": "혼자가 아니다", "p": "회복은 개인의 의지만으로 이뤄지지 않는다. 지지하는 관계, 안정적 일상, 회복 공동체 같은 자원이 두터울수록 회복이 유지된다. 회복을 개인의 과제가 아니라 그를 둘러싼 관계와 사회가 함께 떠받치는 과정으로 볼 때, 더 지속 가능한 결과가 나온다."}]'::jsonb, advanced='[{"h": "회복 개념의 확장", "p": "''회복''의 정의는 단순한 사용 통제를 넘어 건강·웰빙 전반으로 확장되어 왔다. 이 확장이 회복자본 개념과 회복지향 시스템(ROSC)의 이론적 토대가 되었으며, 성공의 지표도 단약률에서 삶의 질·사회통합·지속되는 웰빙으로 넓어졌다."}, {"h": "자연 회복과 다양한 경로", "p": "모든 회복이 전문 치료를 거치는 것은 아니다. 상당수가 공식 치료 없이 회복(자연 회복)하며, 회복의 경로는 12단계, 세속적 자조, 약물치료, 신앙 공동체 등으로 다양하다. ''하나의 올바른 길''을 전제하지 않고 여러 경로를 인정하는 것이 현대 회복 담론의 특징이다."}, {"h": "당사자·공동체 관점", "p": "회복 현장의 관점에서 회복의 핵심 동력은 관계와 소속, 그리고 자기 이야기의 재구성이다. 회복 공동체는 같은 경험을 가진 사람들이 서로를 지지하며 정체성을 회복하는 장이며, 신앙·생태 기반 회복 마을처럼 삶 전체를 재건하는 모델이 그 확장된 형태로 주목받는다."}]'::jsonb, updated_at=now() WHERE id='recovery';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "재발은 회복 과정에서 중단했던 물질 사용이나 행동으로 되돌아가는 것을 말한다. 만성질환에서 흔한 현상으로 이해되며, 도덕적 실패가 아니라 치료와 전략을 재조정하라는 신호로 다루는 것이 회복에 유리하다."}, {"h": "왜 일어나나", "p": "고위험 상황, 부정적 정서(불안·우울·분노·외로움), 단서 노출, 방심이 주요 유발 요인이다. ''한 번쯤은 괜찮다''는 생각, 갈망을 견디는 기술의 부족, 지지 관계의 약화가 재발로 이어진다. 재발은 대개 갑작스러운 사건이 아니라 그 이전부터 쌓인 과정의 결과다."}, {"h": "어떻게 다루나", "p": "재발을 실패로 낙인찍으면 수치심 때문에 오히려 회복 시도를 포기하게 된다. 대신 ''무엇이 재발을 불렀는가''를 분석해 계획을 보강하는 학습 기회로 삼는 것이 핵심이다. 한 번의 실수(lapse)가 완전한 재발로 번지지 않도록 조기에 대응하는 것도 중요하다."}, {"h": "예방", "p": "고위험 상황을 미리 파악하고 그때의 대처를 준비하는 것, 갈망을 견디는 기술, 지지 관계의 유지, 균형 잡힌 생활이 재발 위험을 낮춘다. 재발예방은 회복의 부속이 아니라 회복 그 자체의 핵심 기술이다."}]'::jsonb, advanced='[{"h": "실수와 재발의 구분", "p": "임상에서는 일회적 실수(lapse)와 이전 패턴으로의 완전한 복귀(relapse)를 구분한다. ''한 번 무너졌으니 다 끝났다''는 절제 위반 효과(AVE)가 실수를 재발로 키우는 심리 기제로 지목되며, 이 인지 왜곡을 다루는 것이 재발예방의 핵심이다."}, {"h": "만성질환 모델과 재발", "p": "중독을 만성·재발성 질환으로 보는 관점에서 재발률은 당뇨·고혈압 같은 다른 만성질환과 비교되곤 한다. 이 틀은 재발을 치료 실패가 아니라 지속 관리가 필요하다는 신호로 재해석하게 하며, 일회성 치료가 아닌 장기 관리의 근거가 된다."}, {"h": "당사자 관점", "p": "당사자에게 재발의 가장 큰 위험은 재발 그 자체보다 그것이 부르는 수치심과 자기 낙인이다. ''역시 나는 안 된다''는 학습된 무기력이 회복 시도를 접게 만든다. 그래서 재발을 다루는 회복 공동체의 비판단적 태도가 실질적 회복 유지에 결정적이다."}]'::jsonb, updated_at=now() WHERE id='relapse';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "12단계 프로그램은 익명의 알코올중독자(AA)에서 시작해 여러 중독으로 확장된 상호원조 기반 회복 프로그램이다. 무력함의 인정, 자기 성찰, 보상, 동료 지지, 봉사를 축으로 하며, 후원자(스폰서)와 모임 공동체가 회복을 떠받친다."}, {"h": "어떻게 작동하나", "p": "정기 모임에서 자신의 이야기를 나누고, 먼저 회복한 후원자의 안내를 받으며 단계를 밟아간다. ''혼자 힘으로 통제할 수 없음''을 인정하는 것에서 출발해, 관계 회복과 타인을 돕는 봉사로 나아간다. 같은 경험을 가진 사람들의 비판단적 지지가 핵심 동력이다."}, {"h": "무엇이 특별한가", "p": "12단계의 힘은 전문가가 아니라 ''같은 경험을 가진 동료''가 서로를 돕는다는 데 있다. 회복한 사람이 다음 사람을 이끄는 구조는 지속적이고 접근성이 높으며, 소속과 정체성의 회복을 제공한다. 무료이고 어디에나 있다는 점도 강점이다."}, {"h": "한계와 다양성", "p": "12단계의 영적 틀이 모두에게 맞는 것은 아니다. 이를 부담스러워하는 사람을 위해 SMART 리커버리 같은 세속적 대안이 있으며, 회복의 길은 하나가 아니라는 인식이 넓어지고 있다. 여러 경로를 함께 인정하는 것이 중요하다."}]'::jsonb, advanced='[{"h": "기원과 확장", "p": "AA는 1935년 빌 윌슨과 로버트 스미스에 의해 시작됐고, 이후 NA(약물)·GA(도박) 등 수많은 12단계 모임으로 확장됐다. 카를 융의 영적 각성에 대한 견해가 초기 형성에 영향을 준 것으로 알려져 있다. 한 사람의 회복 경험이 세계적 회복 운동의 토대가 된 사례다."}, {"h": "효과에 대한 근거", "p": "오랫동안 일화적 근거에 의존한다는 비판이 있었으나, 근래의 통제된 연구들은 12단계 촉진 치료가 단주 유지에서 다른 치료에 못지않거나 더 나은 성과를 보인다고 보고한다. 다만 효과는 참여도·소속감에 크게 좌우되며, 모두에게 동일하게 작동하지는 않는다."}, {"h": "신앙 공동체와의 접점", "p": "12단계의 영적 차원은 신앙 기반 회복 공동체와 자연스럽게 맞닿는다. 무력함의 인정, 자기를 넘어선 것에 대한 의탁, 공동체 안의 회복이라는 요소는 신앙적 회복 서사와 공명한다. 이 점에서 12단계는 세속 치료와 신앙 공동체를 잇는 다리 역할을 하기도 한다."}]'::jsonb, updated_at=now() WHERE id='twelve-step';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "동기강화상담은 변화에 대한 양가감정을 존중하며 당사자 스스로 변화 동기를 찾도록 돕는 협력적 상담 방식이다. 설득·훈계 대신 공감적 경청과 열린 질문으로 저항을 낮추고, 변화를 향한 말을 이끌어낸다."}, {"h": "왜 설득이 아닌가", "p": "''끊어라''는 압박은 흔히 저항을 키운다. 사람은 남이 시켜서가 아니라 스스로 이유를 찾을 때 변한다. 동기강화상담은 이 원리 위에서, 당사자가 자기 삶에서 무엇이 걸리는지 스스로 말하게 해 변화의 동기를 내부에서 끌어낸다."}, {"h": "어떻게 하나", "p": "공감적 경청, 열린 질문, 인정, 요약, 그리고 당사자의 ''변화대화''를 알아차리고 강화하는 것이 핵심 기법이다. 상담자는 답을 주는 전문가가 아니라, 당사자가 자신의 답을 찾도록 돕는 동반자의 위치에 선다."}, {"h": "어디에 쓰이나", "p": "특히 아직 문제를 인정하지 않거나 변화를 망설이는 초기 단계에서 효과적이다. 변화단계 모델과 결합해 각 단계에 맞는 개입을 조율하며, 중독뿐 아니라 다양한 건강행동 변화에 널리 활용된다."}]'::jsonb, advanced='[{"h": "이론적 배경", "p": "동기강화상담은 밀러와 롤닉이 정립했으며, 인간 중심 상담과 자기결정 이론에 뿌리를 둔다. 변화의 동기가 외부 압력이 아니라 개인의 가치·자율성에서 나올 때 지속된다는 전제 위에 서 있다. ''저항''을 내담자의 문제가 아니라 상담 관계의 신호로 재해석한 것이 핵심 전환이다."}, {"h": "변화단계와의 결합", "p": "동기강화상담은 변화단계 모델과 자주 결합된다. 전숙고·숙고 단계에서는 양가감정을 다루고, 준비·실행 단계에서는 계획을 지원하는 식으로 단계에 맞춰 접근을 조율한다. 단계를 무시한 성급한 실행 요구가 오히려 역효과를 낸다는 통찰이 그 바탕이다."}, {"h": "근거와 한계", "p": "동기강화상담은 여러 영역에서 효과가 입증됐지만, 만능은 아니다. 단독으로 장기 변화를 담보하기보다 다른 치료의 진입·참여를 높이는 촉진자 역할이 강조된다. 상담자의 숙련도에 따라 효과 편차가 크다는 점도 지적된다."}]'::jsonb, updated_at=now() WHERE id='motivational-interviewing';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "개입은 부정·저항하는 당사자가 치료를 받아들이도록 가족·전문가가 구조화된 방식으로 돕는 절차다. 방법과 효과에 대해선 접근별로 견해차가 있으며, 대립적 방식보다 관계와 지지를 중시하는 접근이 근거를 얻고 있다."}, {"h": "왜 필요한가", "p": "중독의 특징인 부정 때문에, 당사자가 스스로 문제를 인정하고 도움을 청하기까지 오랜 시간이 걸리곤 한다. 그 사이 피해가 커지므로, 주변이 구조화된 방식으로 치료 진입을 돕는 것이 개입이다. 다만 강압적 개입은 관계를 손상시켜 역효과를 낼 수 있다."}, {"h": "어떻게 하나", "p": "비난·대립이 아니라 걱정과 구체적 도움을 담아, 준비된 방식으로 당사자에게 치료를 권하는 것이 효과적이다. 가족이 감정적으로 폭발하기보다 전문가의 안내를 받아 계획적으로 접근하고, 치료로 갈 실제 경로를 함께 마련해 두는 것이 중요하다."}, {"h": "가족의 준비", "p": "개입은 당사자만의 문제가 아니라 가족 전체의 과제다. 가족 자신의 소진과 동반의존을 함께 다루지 않으면 개입이 지속되기 어렵다. 가족의 회복과 준비가 개입의 성패를 좌우하는 경우가 많다."}]'::jsonb, advanced='[{"h": "대립적 개입의 한계", "p": "과거에는 당사자를 몰아붙이는 대립적 개입(예: 서프라이즈 방식)이 유행했으나, 관계를 손상시키고 저항을 키운다는 비판을 받았다. 근래에는 CRAFT처럼 가족의 관계 기술을 훈련해 비대립적으로 치료 진입을 유도하는 접근이 더 나은 근거를 보인다."}, {"h": "자율성과 강제의 경계", "p": "개입은 당사자의 자율성 존중과 치료 필요성 사이의 긴장을 안고 있다. 어디까지가 지지이고 어디부터가 강압인지의 경계가 모호하며, 이는 강제 치료의 정당성 논쟁과도 맞닿는다. 관계를 해치지 않으면서 변화를 돕는 균형이 관건이다."}, {"h": "가족 체계의 관점", "p": "개입을 개인이 아니라 가족 체계의 문제로 보면, 당사자 한 사람을 바꾸려는 시도보다 가족의 상호작용 패턴을 바꾸는 것이 지속적 변화를 낳는다. 이 관점은 개입을 가족치료·동반의존 회복과 연결한다."}]'::jsonb, updated_at=now() WHERE id='intervention';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "치료는 중독을 완화·관리하기 위한 의학·심리·사회적 개입의 총칭이다. 해독, 약물치료, 인지행동치료, 동기강화상담, 자조모임, 사회적 지원 등이 개인 맞춤으로 조합되며, 단일 치료보다 여러 접근의 통합과 충분한 기간이 성과를 좌우한다."}, {"h": "어떤 단계로 이뤄지나", "p": "급성기의 안전한 해독으로 시작해, 갈망과 재발을 다루는 심리치료·약물치료, 그리고 회복을 일상에서 유지하는 지속관리로 이어진다. 해독만 받고 후속 치료로 연결되지 않으면 재발하기 쉬워, ''치료의 시작을 끝으로 오해''하지 않는 것이 중요하다."}, {"h": "무엇이 효과를 가르나", "p": "개인의 필요에 맞춘 맞춤화, 공존하는 정신질환의 통합적 치료, 충분한 치료 기간, 그리고 치료 이후의 지속적 지원이 성과를 좌우한다. 약물치료로 갈망을 낮추면서 심리치료로 대처 기술을 익히고 자조모임으로 지지를 받는 식의 결합이 단일 접근보다 효과적이다."}, {"h": "접근성의 문제", "p": "효과적인 치료가 존재해도 그것에 닿지 못하면 소용이 없다. 비용, 대기, 지역 격차, 낙인이 치료 진입을 막는 장벽이며, 치료의 질만큼이나 접근성이 중요한 정책 과제로 다뤄진다."}]'::jsonb, advanced='[{"h": "근거 기반 치료의 스펙트럼", "p": "중독 치료는 인지행동치료, 동기강화상담, 유관관리, 약물보조치료 등 근거가 축적된 여러 접근으로 구성된다. 물질·개인에 따라 효과적인 조합이 다르며, ''무엇이 누구에게 맞는가''를 찾는 것이 임상의 과제다. 근거 기반 치료와 실제 현장 사이의 간극도 지속적 문제로 지적된다."}, {"h": "통합 치료의 필요", "p": "중독은 우울·불안·트라우마 등과 흔히 공존하므로, 한쪽만 다루면 재발하기 쉽다. 중독과 공존질환을 함께 다루는 통합 치료가 권장되며, 이는 치료 시스템이 정신건강·일차의료와 연계되어야 함을 의미한다."}, {"h": "자발성과 강제 치료 논쟁", "p": "치료의 효과는 당사자의 동기와 밀접하다. 이 때문에 형사사법을 통한 강제 치료의 정당성과 효과가 논쟁적이며, 국제적으로는 자발성에 기반한 근거 기반 치료가 원칙으로 권고된다. 처벌과 치료의 경계를 어떻게 설정할지가 정책적 쟁점이다."}]'::jsonb, updated_at=now() WHERE id='treatment';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "피해감소는 사용의 완전한 중단을 전제하지 않고 중독으로 인한 피해 자체를 줄이는 데 초점을 둔 공중보건 접근이다. 날록손 보급, 주사기 교환, 안전소비시설, 약물 성분 검사 등이 포함되며, 금욕만을 조건으로 삼지 않아 접근성이 높다."}, {"h": "핵심 발상", "p": "''당장 끊을 수 없는 사람이라도 죽거나 병들지 않게 한다''는 것이 핵심이다. 완전한 회복을 유일한 목표로 삼는 대신, 그 과정에서 발생하는 과용 사망·감염·범죄 같은 해악을 먼저 줄인다. 생명을 지키는 것이 회복의 전제라는 관점이다."}, {"h": "어떤 방법이 있나", "p": "과용을 되돌리는 날록손, 감염을 막는 주사기 교환, 안전한 사용을 돕는 감독형 소비시설, 치명적 성분을 걸러내는 약물 검사, 아편류 대체요법 등이 대표적이다. 이들은 사용자를 처벌 대신 보건 서비스로 연결하는 접점이 되기도 한다."}, {"h": "금욕 접근과의 관계", "p": "피해감소와 금욕 지향은 대립이 아니라 상호보완으로 이해할 수 있다. 피해감소가 생명을 지키며 사람을 치료와 연결하는 첫 접점이 되고, 그 위에서 회복과 단약으로 나아갈 수 있다. 다만 두 접근 사이에는 철학적 긴장도 존재한다."}]'::jsonb, advanced='[{"h": "근거와 국제적 위상", "p": "피해감소는 HIV·간염 확산 억제, 과용 사망 감소에서 근거가 두텁고, UNAIDS·WHO 등 국제기구가 지지하는 접근이다. 최근 유엔 차원에서도 피해감소를 인정하는 결의가 채택되며 국제 규범으로 자리 잡아가고 있다."}, {"h": "가치 충돌의 최전선", "p": "피해감소는 회복 정책에서 가치 충돌이 가장 첨예한 지점이다. ''사용을 용인·조장한다''는 도덕적 비판과, ''생명을 지키는 실용적 개입''이라는 근거 기반 옹호가 맞선다. 같은 데이터도 상반된 가치 프레임에서 다르게 해석된다."}, {"h": "회복 연속선 안의 위치", "p": "피해감소를 회복의 반대가 아니라 회복 연속선의 한 단계로 보는 관점이 확산되고 있다. 생명을 지키고 관계를 유지하는 것이 이후 치료·회복의 토대가 된다는 것이다. 이 관점은 회복지향 시스템(ROSC)이 예방부터 회복까지를 하나로 잇는 틀과 맞닿는다."}]'::jsonb, updated_at=now() WHERE id='harm-reduction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "사이키델릭 보조치료는 실로시빈·MDMA 등 환각·유사 물질을 구조화된 심리치료와 결합해 우울·PTSD·중독 등을 치료하려는 접근이다. 오락적 사용과는 구분되는, 통제된 치료 맥락이 핵심이다."}, {"h": "어떻게 작동하나", "p": "약물 단독이 아니라 훈련된 치료자의 준비·동반·통합 과정과 결합된다. 안전한 세팅에서 진행되는 세션과 그 경험을 일상에 통합하는 후속 치료가 한 세트를 이룬다. 물질 자체보다 ''세트와 세팅'', 그리고 심리치료의 결합이 성과를 좌우한다."}, {"h": "중독 치료로서의 가능성", "p": "일부 임상시험에서 알코올·니코틴 등에 대한 사이키델릭 보조치료의 가능성이 보고됐다. 굳어진 사고·행동 패턴을 유연하게 만들고 새로운 관점을 여는 경험이, 회복의 전환점이 될 수 있다는 가설이 연구되고 있다."}, {"h": "신중함이 필요하다", "p": "아직 연구 단계이며, 규제 판단과 근거는 진화 중이다. 안전한 임상 세팅과 훈련된 치료자가 필수이고, 자가 사용은 전혀 다른 위험을 수반한다. 과장된 기대와 오락적 사용을 경계하며 신중히 다뤄야 하는 영역이다."}]'::jsonb, advanced='[{"h": "연구 현황과 규제", "p": "실로시빈·MDMA 보조치료는 여러 임상시험에서 가능성이 보고됐고 일부 지역에서 제도화가 진행되지만, 규제 승인 상황은 나라·물질별로 다르고 계속 변한다. 근거의 질, 눈가림의 어려움, 장기 안전성 등 방법론적 과제도 남아 있다."}, {"h": "기전 가설", "p": "사이키델릭이 신경가소성을 촉진하고, 경직된 자기·세계 인식을 일시적으로 유연하게 만들어 새로운 통찰과 행동 변화를 가능하게 한다는 가설이 제시된다. 다만 이 기전과 치료 효과의 연결은 아직 확립되지 않았다."}, {"h": "오락적 사용과의 경계", "p": "치료적 사용의 핵심은 통제된 세팅·전문가 동반·심리치료 통합이며, 이는 오락적·자가 사용과 근본적으로 다르다. 대중적 관심이 이 경계를 흐리고 자가 사용을 부추길 위험이 있어, 치료 맥락과 오락적 사용을 명확히 구분하는 것이 중요하다."}]'::jsonb, updated_at=now() WHERE id='psychedelic-therapy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "세마글루타이드 등 비만·당뇨 치료용 GLP-1 수용체 작용제가 알코올·니코틴 등에 대한 갈망을 줄일 수 있다는 관찰이 이어지며, 중독 치료제로서의 가능성이 활발히 연구되는 신흥 영역이다. 아직 중독에 대한 확립된 적응증은 아니다."}, {"h": "어떻게 주목받게 됐나", "p": "체중 감량·당뇨 목적으로 GLP-1 약물을 쓰던 사람들이 술·담배에 대한 갈망도 줄었다고 보고하는 사례가 이어지면서 연구가 촉발됐다. 음식에 대한 갈망을 줄이는 작용이 다른 중독 물질의 갈망에도 미칠 수 있다는 가설이다."}, {"h": "기전 가설", "p": "GLP-1 약물이 뇌의 보상회로에 작용해 물질·음식이 주는 보상감을 낮춘다는 것이 유력한 가설이다. 보상에 대한 반응 자체를 줄여 갈망을 완화한다면, 여러 중독에 공통으로 적용될 가능성이 있다는 점에서 주목받는다."}, {"h": "신중한 기대", "p": "흥미로운 가능성이지만 아직 연구 단계다. 중독 치료제로 확립되려면 더 많은 임상 근거가 필요하며, 효과·안전성·적정 대상이 아직 규명 중이다. 과장된 기대를 경계하며 근거의 축적을 지켜봐야 하는 영역이다."}]'::jsonb, advanced='[{"h": "연구의 초기 단계", "p": "GLP-1 약물의 중독 치료 효과는 동물 연구와 관찰·소규모 연구에서 신호가 보고되는 초기 단계다. 대규모 무작위 대조시험의 결과가 축적되어야 하며, 현재로서는 중독에 대한 표준 치료가 아니다."}, {"h": "보상회로 공통 기전의 함의", "p": "만약 GLP-1이 음식·알코올·니코틴 등 여러 대상의 갈망을 공통으로 줄인다면, 이는 음식중독과 물질중독이 공유하는 보상 기전을 뒷받침하는 근거가 될 수 있다. 중독을 가로지르는 공통 치료 표적의 가능성을 시사한다."}, {"h": "접근·형평성 문제", "p": "GLP-1 약물은 수요·비용·공급 문제를 안고 있어, 중독 치료로 확장될 경우 접근 형평성이 쟁점이 될 수 있다. 신약이 회복의 새로운 도구가 되더라도, 누가 그것에 접근할 수 있는가라는 정책 과제가 함께 제기된다."}]'::jsonb, updated_at=now() WHERE id='glp1-and-craving';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "회복자본은 회복을 시작하고 유지하는 데 동원할 수 있는 개인적·사회적·공동체적 자원의 총량이다. 관계망, 경제적 안정, 지지 공동체, 자기효능감, 의미와 목적 등을 포함하며, 이 자본이 두터울수록 회복이 지속될 가능성이 높다."}, {"h": "어떤 자원인가", "p": "흔히 세 층으로 나뉜다. 개인적 자본(건강·기술·자기효능감), 사회적 자본(가족·친구·지지 관계), 공동체적 자본(회복 모임·서비스·사회적 수용)이다. 이 자원들이 서로 맞물려 회복을 떠받친다."}, {"h": "왜 중요한가", "p": "같은 어려움을 겪어도 지지적 공동체·안정적 일자리·신뢰 관계를 가진 사람이 그렇지 못한 사람보다 회복을 더 잘 유지한다. 회복자본은 회복을 개인의 병리나 의지가 아니라 ''가진 자원''의 문제로 재구성하며, 강점에 주목하게 한다."}, {"h": "어떻게 쌓나", "p": "회복자본은 고정된 것이 아니라 키울 수 있다. 관계를 회복하고, 안정적 주거·일자리를 마련하고, 회복 공동체에 소속되고, 작은 성공으로 자기효능감을 쌓는 과정이 회복자본을 두텁게 한다. 회복지향 시스템(ROSC)은 바로 이 자본을 키우는 것을 목표로 삼는다."}]'::jsonb, advanced='[{"h": "개념의 기원과 발전", "p": "회복자본은 그랜필드와 클라우드가 제시한 개념으로, 회복을 개인의 결핍이 아니라 자원과 역량의 축적으로 보는 강점 기반 관점을 대표한다. 이후 회복지향 시스템(ROSC)과 회복 관리의 이론적 토대가 되었으며, BARC-10 같은 측정 도구도 개발됐다."}, {"h": "상호 강화의 역동", "p": "회복자본과 회복은 상호 강화한다. 초기의 단약이 관계 회복·안정 같은 긍정적 결과를 낳고, 그렇게 축적된 자본이 다시 단약을 지속시킨다. 이 선순환을 어떻게 촉발·유지하느냐가 회복 지원의 핵심 설계 원리가 된다."}, {"h": "공동체적 회복자본", "p": "회복자본은 개인 차원을 넘어 공동체 차원에서 축적된다. 회복 공동체·회복 마을은 소속·의미·역할·자립 기반을 함께 제공해 공동체적 회복자본을 키운다. 이는 회복을 개인 치료가 아니라 사회적 인프라의 문제로 보게 하며, 신앙·생태 기반 회복 마을 모델의 이론적 근거가 된다."}]'::jsonb, updated_at=now() WHERE id='recovery-capital';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "해독(디톡스)은 체내 물질을 안전하게 제거하며 급성 금단을 의학적으로 관리하는 초기 단계다. 회복의 시작일 뿐 치료 자체는 아니며, 이후 지속적 재활·관리로 이어지지 않으면 재발하기 쉽다."}, {"h": "왜 의학적 관리가 필요한가", "p": "물질에 따라 금단이 위험할 수 있다. 특히 알코올·벤조디아제핀 금단은 경련·섬망으로 생명을 위협할 수 있어 반드시 의료 감독이 필요하다. 해독은 이 위험한 시기를 안전하게 넘기며 다음 치료로 넘어갈 발판을 마련하는 과정이다."}, {"h": "흔한 오해", "p": "''해독을 마치면 치료가 끝났다''는 오해가 재발의 흔한 원인이다. 해독은 몸에서 물질을 빼는 것일 뿐, 갈망·재발을 다루는 심리·사회적 치료가 이어져야 회복이 시작된다. 해독만 반복하고 후속 치료로 연결되지 않는 ''회전문'' 현상이 문제로 지적된다."}, {"h": "이후로의 연결", "p": "해독의 성패는 그다음 치료로 얼마나 잘 연결되느냐에 달려 있다. 해독 직후가 재발 위험이 가장 높은 시기이므로, 심리치료·약물치료·자조모임·회복 주거 등 지속 관리로 끊김 없이 이어지는 것이 핵심이다."}]'::jsonb, advanced='[{"h": "금단 관리의 임상", "p": "해독은 물질별 금단 양상에 맞춰 이뤄진다. 알코올 금단에는 벤조디아제핀을 이용한 관리(CIWA-Ar 척도 기반), 아편류 금단에는 대체요법 등이 활용된다. 안전한 해독은 이후 치료 참여의 전제가 되지만, 그 자체로는 장기 성과를 담보하지 못한다."}, {"h": "과용 위험의 역설", "p": "해독으로 내성이 떨어진 상태에서 재사용하면 예전 용량이 치명적 과용이 될 수 있다. 특히 아편류에서 이 위험이 크며, 해독 후 재발 시 과용 사망 위험이 급증한다. 이 역설은 해독을 단독으로 시행하는 것의 위험성을 보여준다."}, {"h": "당사자 관점", "p": "해독은 신체적으로 힘겨운 시기이자, 회복 동기가 흔들리기 쉬운 취약한 시점이다. 이 시기에 비판단적 지지와 다음 단계로의 명확한 연결이 없으면 쉽게 이탈한다. 해독을 ''통과 의례''가 아니라 지지가 필요한 관문으로 다루는 관점이 중요하다."}]'::jsonb, updated_at=now() WHERE id='detoxification';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "약물보조치료(MAT)는 약물치료를 심리·사회적 지원과 결합해 중독을 관리하는 근거 기반 접근이다. 특히 아편류 사용장애에서 메타돈·부프레노르핀·날트렉손 등이 갈망과 과용 위험을 낮춰 효과가 입증됐다."}, {"h": "어떻게 작동하나", "p": "약물이 갈망과 금단을 안정시키면, 당사자는 생존과 사용 조절에 매달리는 대신 일상 회복(관계·일·심리치료)에 집중할 수 있게 된다. 약물은 회복을 대신하는 것이 아니라, 회복이 가능한 안정된 토대를 만들어 준다."}, {"h": "낙인이라는 장벽", "p": "''약으로 약을 바꾼다''는 오해와 낙인이 MAT 접근을 가로막는 큰 장벽이다. 그러나 근거는 MAT가 아편류 사용장애에서 사망·재발·감염을 줄이는 가장 효과적인 접근 중 하나임을 보여준다. 이 낙인을 줄이는 것이 치료 접근성의 핵심 과제다."}, {"h": "통합이 핵심", "p": "MAT의 ''A(보조)''가 강조하듯, 약물은 심리·사회적 지원과 결합될 때 가장 효과적이다. 약물만으로도 과용을 줄이지만, 상담·자조·사회 지원이 함께할 때 삶의 회복으로 이어진다."}]'::jsonb, advanced='[{"h": "근거와 용어의 진화", "p": "MAT는 아편류 사용장애에서 사망률을 크게 낮추는 것으로 입증된 가장 강력한 근거 기반 개입에 속한다. 근래에는 ''보조(assisted)''라는 표현이 약물을 부차적으로 여기게 한다는 비판에서, MOUD(아편류사용장애 약물치료)라는 용어가 더 선호되기도 한다."}, {"h": "접근성과 정책", "p": "효과가 입증됐음에도 규제·낙인·인프라 부족으로 MAT 접근성은 여전히 제한적이다. 처방 자격 완화, 교정시설 내 제공, 원격의료 확대 등이 접근성을 높이는 정책으로 논의된다. 피해감소 관점에서 MAT 확대는 과용 위기 대응의 핵심 축이다."}, {"h": "단약 지향과의 긴장", "p": "MAT는 단약만을 성공으로 보는 전통적 관점과 긴장을 빚기도 한다. 유지요법을 ''진짜 회복이 아니다''로 보는 시각과, 생명을 지키고 기능을 회복시키는 것이 우선이라는 피해감소 관점이 충돌한다. 이 긴장은 회복의 정의를 둘러싼 더 큰 논쟁의 일부다."}]'::jsonb, updated_at=now() WHERE id='medication-assisted-treatment';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "메타돈은 장시간 작용하는 아편류로, 아편류 사용장애 치료에서 금단과 갈망을 안정시키는 대체요법으로 오래 쓰였다. 통제된 프로그램에서 제공되며 과용·범죄를 줄이는 효과가 있다."}, {"h": "어떻게 작동하나", "p": "메타돈은 아편류 수용체에 작용해 금단과 갈망을 억제하되, 서서히 오래 작용해 ''취하는'' 효과 없이 안정을 준다. 이로써 헤로인 등 불법 아편류를 찾는 행동과 그에 따른 위험(과용·감염·범죄)을 줄이고, 일상 기능을 회복하게 한다."}, {"h": "어떻게 제공되나", "p": "메타돈은 오남용 위험 때문에 통상 인증된 프로그램에서 관리·투약된다. 매일 방문해 복용하는 구조가 접근성의 제약이 되기도 하지만, 동시에 규칙적 관리와 연결의 기회가 되기도 한다."}, {"h": "의의", "p": "메타돈 유지요법은 수십 년간 아편류 사용장애 관리의 근간이었다. 과용 사망과 HIV 감염을 줄이는 공중보건적 효과가 입증됐으며, 피해감소 접근의 대표적 도구로 자리 잡았다."}]'::jsonb, advanced='[{"h": "역사와 근거", "p": "메타돈 유지요법은 1960년대부터 아편류 의존 관리에 사용되어, 가장 오래 검증된 약물치료다. 사망률·범죄·감염 감소에 대한 근거가 두텁지만, 프로그램 접근성과 매일 방문 부담이 한계로 지적된다."}, {"h": "낙인과 규제", "p": "메타돈은 ''중독을 다른 약물로 대체한다''는 낙인과 엄격한 규제에 오래 묶여 있었다. 이 규제가 안전을 위한 것인 동시에 접근을 어렵게 하는 이중성을 지니며, 규제 완화와 안전 사이의 균형이 정책 쟁점이다."}, {"h": "부프레노르핀과의 비교", "p": "메타돈은 강력하지만 과용·상호작용 위험이 있어 통제된 환경을 요구한다. 부분작용제인 부프레노르핀은 상대적으로 안전해 외래 처방이 가능하다. 두 약물은 대체가 아니라 환자 상황에 따라 선택되는 상호보완적 선택지다."}]'::jsonb, updated_at=now() WHERE id='methadone-med';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "부프레노르핀은 부분작용 아편류로, 갈망·금단을 조절하면서 과용 위험이 상대적으로 낮아 아편류 사용장애 치료에 널리 쓰인다. 외래에서 처방 가능해 접근성이 높은 편이다."}, {"h": "왜 더 안전한가", "p": "부프레노르핀은 아편류 수용체에 ''부분적으로만'' 작용해, 일정 용량 이상에서는 효과가 더 커지지 않는 천장 효과가 있다. 이 때문에 호흡억제·과용 위험이 상대적으로 낮아, 병원 밖 외래에서도 처방·관리가 가능하다."}, {"h": "어떤 이점이 있나", "p": "매일 시설을 방문해야 하는 메타돈과 달리, 외래 처방이 가능해 접근성과 일상 유지에 유리하다. 날록손과 복합된 제형은 오남용을 억제하도록 설계돼 있다. 이 접근성 덕분에 치료의 문턱을 낮추는 데 기여한다."}, {"h": "의의", "p": "부프레노르핀은 아편류 위기 대응에서 접근 가능한 치료의 핵심으로 부상했다. 처방 자격 규제 완화, 원격의료 처방 확대 등이 이 약물의 접근성을 넓히는 정책으로 추진되고 있다."}]'::jsonb, advanced='[{"h": "약리적 특성", "p": "부프레노르핀은 아편류 수용체의 부분작용제이자 강한 수용체 결합력을 지녀, 다른 아편류의 작용을 차단하는 성질도 있다. 이 때문에 투여 시점(금단이 시작된 뒤 시작)이 중요하며, 잘못된 시점의 투여는 급성 금단을 유발할 수 있다."}, {"h": "접근성 정책", "p": "부프레노르핀의 강점은 외래 접근성이다. 여러 나라가 처방 자격 요건을 완화하고 원격 처방을 허용해 치료 공백을 줄이려 한다. 이는 과용 위기 대응에서 ''치료를 사람에게 가까이 가져가는'' 전략의 핵심이다."}, {"h": "유지요법을 둘러싼 논쟁", "p": "메타돈과 마찬가지로, 부프레노르핀 유지요법을 ''완전한 회복''으로 볼지에 대한 관점 차이가 있다. 생명과 기능을 지키는 것을 우선하는 피해감소 관점과 단약을 지향하는 관점의 긴장이 여기서도 나타난다."}]'::jsonb, updated_at=now() WHERE id='buprenorphine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "날트렉손은 아편류·알코올의 보상 효과를 차단하는 약물로, 사용해도 도취를 느끼기 어렵게 해 재발을 줄인다. 지속형 주사제 형태가 순응도를 높인다."}, {"h": "어떻게 작동하나", "p": "날트렉손은 아편류 수용체를 차단해, 아편류를 사용해도 효과가 나타나지 않게 한다. 알코올에서도 음주의 보상감을 줄여, ''마셔도 예전 같은 쾌감이 없어'' 음주 동기가 약해지도록 돕는다. 갈망을 부추기는 보상 자체를 차단하는 접근이다."}, {"h": "어떤 이점이 있나", "p": "메타돈·부프레노르핀과 달리 그 자체로 의존성이 없고, 월 1회 지속형 주사제는 매일 복용의 부담을 덜어 순응도를 높인다. 단약을 지향하는 사람에게 적합한 선택지다."}, {"h": "주의점", "p": "아편류 차단제이므로, 아편류가 몸에서 충분히 빠진 뒤 시작해야 급성 금단을 피할 수 있다. 또 차단 상태에서 무리하게 아편류를 사용하려다 과용에 이를 위험이 있어, 사용자 교육이 함께 필요하다."}]'::jsonb, advanced='[{"h": "작용 기제의 차이", "p": "날트렉손은 작용제(메타돈)·부분작용제(부프레노르핀)와 달리 순수 길항제로, 보상을 ''대체''하는 것이 아니라 ''차단''한다. 이 차이 때문에 유지요법과는 다른 치료 철학—단약 지향—에 부합하며, 환자 선택과 동기가 성과에 크게 작용한다."}, {"h": "알코올에서의 근거", "p": "날트렉손은 알코올사용장애에서 음주량·재발을 줄이는 근거를 가진 몇 안 되는 약물 중 하나다. 일부 접근(예: 신클레어 방법)은 음주 시점에 복용해 보상 소거를 유도하기도 한다. 다만 순응도와 개인차가 효과를 좌우한다."}, {"h": "순응도와 지속형 제형", "p": "경구 날트렉손은 복용 중단이 쉬워 순응도가 낮은 편이다. 월 1회 지속형 주사제는 이 문제를 완화하지만 비용·접근성 제약이 있다. 약물의 효과만큼이나 ''어떻게 지속시키는가''가 실제 성과를 결정한다."}]'::jsonb, updated_at=now() WHERE id='naltrexone';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "날록손은 아편류 과용의 호흡억제를 신속히 되돌리는 응급 해독제로, 생명을 구하는 피해감소의 핵심 도구다. 비전문가도 쓸 수 있는 비강 스프레이 보급이 확대되고 있다."}, {"h": "어떻게 작동하나", "p": "날록손은 아편류 수용체를 강하게, 그러나 짧게 차단해 과용으로 멈춘 호흡을 되살린다. 과용으로 의식·호흡을 잃은 사람에게 즉시 투여하면 몇 분 안에 효과가 나타나, 응급실 도착 전에 생명을 구할 수 있다."}, {"h": "왜 중요한가", "p": "과용 사망은 대부분 호흡억제로 일어나며, 이는 날록손으로 되돌릴 수 있다. 펜타닐 등 강력한 합성 아편류가 확산되면서, 사용자·가족·주변인이 날록손을 즉시 쓸 수 있게 하는 것이 과용 사망을 막는 가장 직접적인 방법이 되었다."}, {"h": "어떻게 보급되나", "p": "약국·지역사회·응급대응자에게 널리 보급되고, 사용법 교육이 병행된다. 작용 시간이 짧아 효과가 사라지면 다시 위험해질 수 있으므로, 투여 후 반드시 응급의료로 연결해야 한다."}]'::jsonb, advanced='[{"h": "공중보건 도구로서의 확산", "p": "날록손 보급은 피해감소의 대표 성공 사례로, 여러 나라가 처방전 없이 접근 가능하게 하고 지역사회 배포를 확대했다. ''사용을 중단시키지 못하더라도 죽지 않게 한다''는 원칙을 구현하는 개입이다."}, {"h": "펜타닐 시대의 과제", "p": "펜타닐 같은 초강력 아편류 과용에는 여러 번의 날록손 투여가 필요할 수 있어, 단일 투여로 부족한 경우가 늘고 있다. 이에 고용량 제형과 신속 재투여의 필요가 커지고 있으며, 보급 규모와 접근성이 계속 확대되는 추세다."}, {"h": "낙인 논쟁", "p": "날록손 보급이 ''위험한 사용을 조장한다''는 비판이 제기되기도 하지만, 근거는 이를 뒷받침하지 않는다. 생명을 구하는 것이 회복의 전제라는 피해감소의 원칙이, 도덕적 우려에 대한 답으로 제시된다."}]'::jsonb, updated_at=now() WHERE id='naloxone';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "유관관리는 약물 음성 결과 등 바람직한 행동에 즉각적 보상을 주어 회복 행동을 강화하는 근거 기반 치료다. 조작적 조건화 원리를 치료에 적용한 대표 사례로, 특히 자극제 사용장애에서 효과가 크다."}, {"h": "어떻게 작동하나", "p": "정해진 기간 물질을 사용하지 않았음이 확인되면(예: 소변검사 음성) 즉시 보상(상품권·소액 인센티브 등)을 제공한다. 즉각적이고 확실한 보상이 회복 행동을 강화하는 것이다. 물질의 즉각적 보상에 맞서, 회복 행동에도 즉각적 보상을 붙이는 발상이다."}, {"h": "왜 효과적인가", "p": "중독은 즉각적 보상에 강하게 반응하는 상태다. 유관관리는 이 원리를 역이용해, 먼 미래의 이득 대신 지금의 확실한 보상으로 회복 행동을 유도한다. 특히 효과적인 약물치료가 없는 자극제(코카인·메스암페타민) 사용장애에서 근거가 두텁다."}, {"h": "한계와 오해", "p": "''돈으로 회복을 산다''는 오해와, 보상이 끝나면 효과가 유지되기 어렵다는 지속성 문제가 지적된다. 그러나 초기 회복 행동을 확립하는 데 강력하며, 다른 치료와 결합할 때 효과가 지속되는 것으로 보고된다."}]'::jsonb, advanced='[{"h": "근거와 저활용의 역설", "p": "유관관리는 가장 강력한 근거를 가진 행동 치료 중 하나이지만, ''보상 제공''에 대한 도덕적 거부감과 재정·행정 부담 때문에 실제로는 저활용된다. 근거와 현장 적용 사이의 간극이 큰 대표적 사례다."}, {"h": "자극제 치료의 공백", "p": "아편류·알코올과 달리 자극제 사용장애에는 승인된 효과적 약물치료가 없다. 이 공백에서 유관관리는 가장 근거 있는 개입으로 부각되며, 자극제 과용이 늘어나는 상황에서 그 중요성이 재조명되고 있다."}, {"h": "윤리와 설계", "p": "인센티브의 크기·방식(예: 당첨식 보상)을 어떻게 설계하느냐가 효과와 지속성을 좌우한다. ''외적 보상이 내적 동기를 해친다''는 우려에 대해서는, 초기 행동 형성 후 자연적 보상(관계·성취)으로 이행시키는 설계가 답으로 제시된다."}]'::jsonb, updated_at=now() WHERE id='contingency-management';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "재발예방은 고위험 상황을 식별하고 대처 기술을 훈련해 재발을 줄이는 인지행동 기반 접근이다. 갈망 대처, 거절 기술, 왜곡된 사고의 재구성, 균형 잡힌 생활 등을 다루며, 재발을 실패가 아니라 학습 기회로 재구성한다."}, {"h": "어떻게 작동하나", "p": "먼저 ''어떤 상황에서 위험해지는지''(장소·사람·감정·시간)를 구체적으로 파악하고, 그때 무엇을 할지 대처 계획을 미리 세운다. 갈망이 파도처럼 밀려왔다 잦아든다는 것을 이해하고 견디는 기술, 권유를 거절하는 기술, ''한 번쯤은''이라는 생각에 반박하는 훈련이 핵심이다."}, {"h": "왜 중요한가", "p": "치료로 사용을 멈추는 것과 그 상태를 유지하는 것은 다른 과제다. 재발예방은 회복을 ''유지''하는 기술을 다루며, 이것이 없으면 치료 효과가 고위험 상황에서 쉽게 무너진다. 그래서 재발예방은 회복의 부속이 아니라 회복의 핵심 기술로 다뤄진다."}, {"h": "생활의 균형", "p": "극단적 절제나 과로, 고립은 오히려 재발 위험을 키운다. 수면·운동·관계·의미 있는 활동이 균형을 이루는 생활 자체가 재발을 막는 토대가 된다. 재발예방은 위기 순간의 대처만이 아니라 평상시 삶의 재건까지 포함한다."}]'::jsonb, advanced='[{"h": "인지행동 모델의 적용", "p": "재발예방은 말렛의 인지행동 재발예방 모델에 뿌리를 둔다. 고위험 상황–대처 반응–자기효능감–결과기대의 연쇄를 분석해, 어느 고리를 끊을지 겨냥한다. 절제 위반 효과(AVE) 같은 인지 왜곡을 다루는 것이 이 접근의 특징이다."}, {"h": "마음챙김 기반 확장", "p": "근래에는 마음챙김 기반 재발예방(MBRP)처럼 갈망을 억누르기보다 판단 없이 관찰하고 흘려보내는 접근이 더해졌다. 갈망과 싸우는 대신 그것과 함께 머무는 기술이, 갈망을 촉발하는 자동 반응의 고리를 약화시킨다는 근거가 축적되고 있다."}, {"h": "당사자 관점", "p": "재발예방의 실질은 ''위기의 순간에 혼자가 아니게 하는 것''이다. 계획을 세워도 고립된 상태에서는 무너지기 쉬우므로, 즉시 연락할 지지 관계와 회복 공동체가 대처 계획의 핵심 자원이 된다. 기술과 관계가 함께 갈 때 재발예방이 작동한다."}]'::jsonb, updated_at=now() WHERE id='relapse-prevention';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "치료공동체는 공동생활 속에서 동료 상호작용과 구조화된 일상을 통해 회복을 돕는 장기 치료 모델이다. 공동체 자체를 변화의 도구로 삼으며, 신앙 기반·생태 기반 회복 공동체와도 접점이 있다."}, {"h": "어떻게 작동하나", "p": "함께 생활하며 역할과 책임을 나누고, 규칙 있는 일상과 동료 간 상호 피드백을 통해 새로운 삶의 방식을 익힌다. 개인의 변화가 공동체 안에서 지지되고 검증되며, ''공동체가 곧 치료자''라는 원리가 작동한다. 대개 수개월 이상의 장기 과정이다."}, {"h": "왜 효과적인가", "p": "고립되기 쉬운 회복 초기에 안정적 환경과 소속을 제공하고, 같은 경험을 가진 동료들의 지지 속에서 정체성을 재구성할 수 있게 한다. 위험한 환경으로 곧바로 돌아가는 대신, 회복의 기반을 다질 시간과 공간을 준다."}, {"h": "현대적 형태", "p": "전통적 치료공동체는 신앙 기반 회복 공동체, 생태·농업 기반 회복 마을 등 다양한 형태로 확장되고 있다. 삶 전체를 재건하는 장기 공동체 모델은, 치료를 넘어 일과 관계와 의미를 함께 회복하는 접근으로 주목받는다."}]'::jsonb, advanced='[{"h": "역사와 명암", "p": "치료공동체 운동은 1950~60년대 시나논 등에서 출발해 큰 영향을 주었으나, 일부는 통제적·폐쇄적으로 변질되며 위험성도 드러냈다. 이 역사는 공동체 기반 회복의 강력한 가능성과, 권력·통제의 위험을 함께 경계해야 함을 보여준다."}, {"h": "근거와 적용", "p": "치료공동체는 특히 중증·만성 사용자, 교정시설 연계 인구에서 효과가 보고된다. 다만 장기·고강도 개입이라 중도 탈락률과 비용이 과제이며, 자발성과 개별화를 강화하는 방향의 개선이 요구된다."}, {"h": "신앙·생태 공동체로의 확장", "p": "현대의 회복 마을은 치료공동체 원리에 신앙적 의미, 농업·생태적 일상, 사회적기업적 자립 기반을 결합한다. 이는 회복을 개인 치료가 아니라 삶의 재건과 공동체 소속의 문제로 보는 관점의 확장이며, 회복지향 시스템(ROSC)이 강조하는 회복자본의 공동체적 축적과 맞닿는다."}]'::jsonb, updated_at=now() WHERE id='therapeutic-community';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "SMART 리커버리는 인지행동·동기강화에 기반한 자조 프로그램으로, 12단계의 영적 틀 대신 자기주도적 도구와 과학적 접근을 강조한다. 12단계와 더불어 회복의 선택지를 넓히는 세속적 대안으로 활용된다."}, {"h": "무엇이 다른가", "p": "12단계가 무력함의 인정과 영적 차원을 강조한다면, SMART는 ''스스로 변화를 관리할 수 있다''는 자기효능감과 실용적 도구를 강조한다. 동기 강화, 충동 대처, 생각·감정·행동 다루기, 균형 잡힌 삶이라는 네 영역의 도구를 배우고 적용한다."}, {"h": "누구에게 맞나", "p": "영적 접근이 맞지 않거나, 자기주도적·인지적 방식을 선호하는 사람에게 대안이 된다. ''평생 회복 중''이라는 정체성보다 문제 해결과 졸업을 지향하는 점도 특징이다. 12단계와 배타적이지 않으며, 두 가지를 함께 활용하는 사람도 있다."}, {"h": "어떻게 운영되나", "p": "훈련된 진행자가 이끄는 모임에서 인지행동 도구를 함께 연습하고, 온라인 자료와 도구가 폭넓게 제공된다. 특정 물질에 국한되지 않고 다양한 중독 행동에 적용할 수 있도록 설계돼 있다."}]'::jsonb, advanced='[{"h": "세속적 대안의 의미", "p": "SMART의 등장은 회복이 하나의 틀(12단계)로 수렴되지 않음을 보여준다. 영적 접근에 거부감을 느끼거나 종교적 배경이 다른 사람에게 회복의 문턱을 낮추며, 회복 경로의 다원화라는 현대적 흐름을 대표한다."}, {"h": "근거 기반과 한계", "p": "SMART는 인지행동·동기강화라는 근거 기반 원리에 뿌리를 두지만, 프로그램 자체의 장기 효과에 대한 대규모 연구는 12단계에 비해 상대적으로 부족하다. 자조 프로그램 특성상 참여도와 진행자 역량이 성과에 영향을 준다."}, {"h": "상호보완의 관점", "p": "12단계와 SMART는 경쟁이 아니라 상호보완으로 이해하는 것이 생산적이다. 사람마다 맞는 길이 다르므로, 여러 선택지를 제공하는 것 자체가 회복 시스템의 강점이 된다. 회복 정책도 단일 모델 강요보다 다양한 경로의 공존을 지향하는 방향으로 간다."}]'::jsonb, updated_at=now() WHERE id='smart-recovery';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "가족치료는 중독을 개인이 아닌 가족 체계의 문제로 보고, 관계 패턴과 의사소통을 다루어 회복을 돕는 접근이다. 동반의존을 완화하고, 가족을 문제의 일부에서 회복의 자원으로 전환한다."}, {"h": "왜 가족인가", "p": "중독은 당사자 한 사람이 아니라 가족 전체에 영향을 주고, 가족의 상호작용이 문제를 지속시키기도 한다. 예컨대 대신 책임을 떠안거나 문제를 감추는 방식이 당사자가 결과를 직면할 기회를 없앤다. 그래서 가족 체계를 함께 다루는 것이 회복에 유리하다."}, {"h": "어떻게 하나", "p": "가족이 함께 상담에 참여해, 문제를 지속시키던 상호작용을 알아차리고 바꿔간다. 건강한 경계 설정, 솔직한 의사소통, 그리고 가족 각자가 자신의 삶을 돌보는 법을 배운다. 당사자를 고치려는 시도에서 관계를 바꾸는 것으로 초점이 옮겨간다."}, {"h": "가족의 회복", "p": "가족치료의 중요한 통찰은 가족 자신도 회복이 필요하다는 것이다. 오랜 돌봄과 갈등으로 지친 가족이 스스로를 돌보고 건강한 경계를 세울 때, 당사자의 회복도 더 잘 지지된다. 회복은 가족 모두의 과제다."}]'::jsonb, advanced='[{"h": "체계론적 관점", "p": "가족치료는 중독을 개인의 병리가 아니라 가족 체계의 항상성 안에서 유지되는 현상으로 본다. 한 사람의 변화가 체계 전체의 균형을 흔들기 때문에, 개인만 치료하면 체계가 그를 다시 이전 역할로 끌어당길 수 있다. 그래서 체계 자체의 변화를 겨냥한다."}, {"h": "근거 기반 가족 개입", "p": "청소년 중독에서 다차원 가족치료(MDFT), 가족 대상 CRAFT 등은 근거가 축적된 접근이다. 이들은 가족의 관계·의사소통 기술을 훈련해 치료 진입과 유지를 높인다. 가족 개입이 당사자 단독 치료보다 나은 성과를 보이는 경우가 보고된다."}, {"h": "동반의존과 공동체", "p": "가족치료는 동반의존 개념 및 알아넌 같은 가족 자조 모임과 연결된다. 나아가 회복 공동체가 가족을 회복의 파트너로 포함할 때, 가족치료는 개별 상담을 넘어 공동체적 회복의 일부가 된다. 이는 가족을 함께 품는 회복 마을 모델과 접점을 갖는다."}]'::jsonb, updated_at=now() WHERE id='family-therapy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "회복 주거·공동체는 회복 초기의 안정적 환경을 제공하는 절주·단약 중심의 공동 주거 및 지역 회복 공동체다. 구조와 또래 지지가 재발 위험이 높은 시기를 넘기는 데 도움을 준다."}, {"h": "왜 필요한가", "p": "치료를 마쳐도 곧바로 예전의 위험한 환경으로 돌아가면 재발하기 쉽다. 회복 주거는 그 사이의 다리로서, 안정적이고 단약이 유지되는 생활 환경 속에서 사회 복귀를 준비하게 한다. 물리적 환경이 회복 유지에 미치는 영향을 반영한 접근이다."}, {"h": "어떻게 운영되나", "p": "함께 사는 규칙(단약 유지, 상호 지지, 책임 분담) 아래 일상을 꾸리며, 또래의 지지와 점진적 자립 준비가 이뤄진다. 치료시설보다 자율적이고 일상에 가까운 환경에서 회복을 생활화한다."}, {"h": "무엇을 제공하나", "p": "안전한 주거, 같은 목표를 가진 또래 관계, 그리고 고용·교육으로 나아가는 발판을 제공한다. 회복이 개인의 의지만이 아니라 안정적 환경과 관계에 달려 있음을 실천으로 보여주는 모델이다."}]'::jsonb, advanced='[{"h": "회복자본으로서의 주거", "p": "안정적 주거는 회복자본의 핵심 요소다. 주거 불안정이 재발·노숙·재수감의 악순환을 부르는 반면, 안정적 회복 주거는 그 고리를 끊는 발판이 된다. 이 점에서 회복 주거는 개인 치료를 넘어선 사회적 회복 인프라로 이해된다."}, {"h": "근거와 질 관리", "p": "회복 주거는 단약 유지와 재발 감소에 기여한다는 근거가 있으나, 시설 간 질 편차가 크고 규제·기준이 미비한 곳이 많다. 안전·운영의 질을 담보하는 인증과 표준화가 과제로 지적된다."}, {"h": "회복 마을로의 확장", "p": "회복 주거의 원리는 신앙·생태 기반 회복 마을로 확장된다. 주거를 넘어 일자리(사회적기업), 농업·생태적 일상, 공동체적 소속을 결합하면, 회복을 일상 전체의 재건으로 이끄는 통합 모델이 된다. 회복지향 시스템(ROSC)이 지향하는 지역사회 기반 회복과 맞닿는 지점이다."}]'::jsonb, updated_at=now() WHERE id='sober-living';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "미네소타 모델은 12단계 철학과 전문 임상을 결합한 중독 치료 모델로, 다학제 팀·동료 지지·단약 지향을 특징으로 한다. 20세기 중반 미국에서 형성되어 현대 재활치료의 한 표준이 되었다."}, {"h": "어떻게 구성되나", "p": "의사·상담사·사회복지사 등 다학제 팀이 협력하고, 회복한 당사자가 상담 인력으로 참여하며, 12단계 원리를 치료 프로그램에 통합한다. 집중적 재활 기간 동안 교육·집단상담·개별상담·자조모임을 결합해 회복의 기초를 다진다."}, {"h": "왜 영향력이 컸나", "p": "전문 임상과 동료 지지라는, 이전에는 분리돼 있던 두 흐름을 결합한 것이 핵심이다. 중독을 질병으로 보는 관점 위에서 전문 치료와 12단계 공동체를 잇는 틀을 제공해, 많은 재활 프로그램의 원형이 되었다."}, {"h": "한계와 진화", "p": "단약 지향의 집중 재활 모델이라 피해감소 접근이나 다양한 경로와 긴장을 빚기도 한다. 근래에는 지속관리·회복지향 시스템(ROSC)의 관점이 더해지며, 단기 집중 치료를 넘어 장기 회복 지원으로 확장되는 흐름에 있다."}]'::jsonb, advanced='[{"h": "임상과 자조의 결합", "p": "미네소타 모델의 역사적 기여는 전문 임상과 12단계 자조를 제도적으로 결합한 데 있다. 이 결합은 중독을 질병으로 규정하면서도 회복을 공동체적 과정으로 보는 이중 관점을 치료 현장에 정착시켰다."}, {"h": "근거와 비판", "p": "미네소타 모델은 널리 확산됐지만, 집중 입원 재활의 비용 대비 효과, 단약 일변도, 표준화된 프로그램이 개인차를 충분히 반영하지 못한다는 비판을 받아왔다. 근거 기반 개별화와 지속관리를 강화하는 방향으로 진화가 요구된다."}, {"h": "회복공동체와의 계보", "p": "미네소타 모델은 치료공동체·회복 주거와 함께 ''공동체 안의 회복''이라는 계보를 이룬다. 전문 치료 이후 회복을 일상에서 유지하는 공동체적 지지의 중요성을 부각하며, 신앙·생태 기반 회복 마을 같은 확장 모델과 문제의식을 공유한다."}]'::jsonb, updated_at=now() WHERE id='minnesota-model';
COMMIT;
-- 확인:
SELECT id, jsonb_array_length(body) b, jsonb_array_length(advanced) a FROM encyclopedia_terms WHERE category='recovery' ORDER BY id;
